<script setup lang="ts">
import {instrumentLabel,instrumentName} from '../utils/instrumentNames'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {ArrowLeftRight,RefreshCw} from 'lucide-vue-next'
import {optionsApi,type LinkedOptions,type LiveOptionChain,type OptionDepth} from '../services/options'
import {LIVE_PERIODS,type IntradaySnapshot,type LiveFrequency} from '../services/live'
import {hasPermission} from '../services/auth'
import {RefreshSchedule} from '../utils/refreshSchedule'
import {depthRadar} from '../utils/depthRadar'
import {formatNumber as n,formatTime,formatTradingDate} from '../utils/format'
import TongdaxinChart from './TongdaxinChart.vue'
const props=withDefaults(defineProps<{futureSymbol:string;paused?:boolean}>(),{paused:false})
const linked=ref<LinkedOptions|null>(null),chain=ref<LiveOptionChain|null>(null),depth=ref<OptionDepth|null>(null),chart=ref<IntradaySnapshot|null>(null)
const chainId=ref(''),symbol=ref(''),side=ref('ALL'),strike=ref(''),frequency=ref<LiveFrequency>(60)
const linkedError=ref(''),chainError=ref(''),depthError=ref(''),chartError=ref('')
const linkedLoading=ref(false),chainLoading=ref(false),depthLoading=ref(false),chartLoading=ref(false),clock=ref(Date.now())
const permitted=computed(()=>hasPermission('options.read'))
const contracts=computed(()=>(chain.value?.contracts??[]).filter(c=>(side.value==='ALL'||c.optionClass===side.value)&&(!strike.value||String(c.strike).includes(strike.value.trim()))))
const selected=computed(()=>chain.value?.contracts.find(c=>c.symbol===symbol.value))
const radar=computed(()=>depthRadar(depth.value,clock.value))
const periodLabel=computed(()=>LIVE_PERIODS.find(p=>p.value===frequency.value)?.label??'')
const maxVolume=computed(()=>Math.max(1,...radar.value.bids.map(r=>r.volume),...radar.value.asks.map(r=>r.volume)))
const stateLabel=computed(()=>props.paused?'页面刷新暂停':depthError.value?'盘口读取失败':!depth.value?'等待期权盘口':radar.value.fresh?'近时盘口':'缓存 / 行情未更新')
let alive=true,generation=0,linkedRequest=0,chainRequest=0,depthRequest=0,chartRequest=0,timer:number|undefined
const linkedSchedule=new RefreshSchedule(5000,60000),chainSchedule=new RefreshSchedule(10000),depthSchedule=new RefreshSchedule(2000),chartSchedule=new RefreshSchedule(3000)
function resetSchedules(){for(const schedule of [linkedSchedule,chainSchedule,depthSchedule,chartSchedule])schedule.reset()}
function text(error:unknown){return error instanceof Error?error.message:'期权行情暂不可用。'}
async function loadLinked(){
 if(!props.futureSymbol||!permitted.value||props.paused||linkedLoading.value)return
 const ticket=++linkedRequest,target=props.futureSymbol;linkedLoading.value=true
 try{const result=await optionsApi.linked(target);if(!alive||ticket!==linkedRequest||target!==props.futureSymbol)return;if(result.requestedFuture!==target)throw new Error('期权标的与当前期货不一致。');linked.value=result;linkedError.value='';result.chains.length?linkedSchedule.defer(30000):linkedSchedule.received('WARMING');if(!result.chains.some(c=>c.id===chainId.value))chainId.value=result.chains[0]?.id??''}
 catch(e){if(alive&&ticket===linkedRequest){linkedError.value=text(e);linkedSchedule.failed()}}finally{if(alive&&ticket===linkedRequest)linkedLoading.value=false}
}
function candidate(){const price=chain.value?.underlying.lastPrice;if(price==null||price<=0)return '';return [...contracts.value].sort((a,b)=>Math.abs(a.strike-price)-Math.abs(b.strike-price))[0]?.symbol??''}
async function loadContracts(){
 if(!chainId.value||props.paused||chainLoading.value)return
 const ticket=++chainRequest,target=chainId.value;chainLoading.value=true
 try{const result=await optionsApi.contracts(target);if(!alive||ticket!==chainRequest||target!==chainId.value)return;if(result.chain.id!==target)throw new Error('期权链不匹配，已停止展示。');chain.value=result;chainError.value='';chainSchedule.received(result.dataStatus);if(!contracts.value.some(c=>c.symbol===symbol.value))symbol.value=candidate()}
 catch(e){if(alive&&ticket===chainRequest){chainError.value=text(e);chainSchedule.failed()}}finally{if(alive&&ticket===chainRequest)chainLoading.value=false}
}
async function loadDepth(){
 if(!symbol.value||props.paused||depthLoading.value)return
 const ticket=++depthRequest,target=symbol.value,version=generation;depthLoading.value=true
 try{const result=await optionsApi.depth(target);if(!alive||ticket!==depthRequest||version!==generation)return;if(result.symbol!==target)throw new Error('期权盘口合约不匹配。');depth.value=result;depthError.value='';depthSchedule.received(result.dataStatus)}
 catch(e){if(alive&&ticket===depthRequest&&version===generation){depthError.value=text(e);depthSchedule.failed()}}finally{if(alive&&ticket===depthRequest)depthLoading.value=false}
}
async function loadChart(){
 if(!symbol.value||props.paused||chartLoading.value)return
 const ticket=++chartRequest,target=symbol.value,selectedFrequency=frequency.value,version=generation;chartLoading.value=true
 try{const result=await optionsApi.chart(target,selectedFrequency);if(!alive||ticket!==chartRequest||version!==generation)return;if(result.symbol!==target||(typeof selectedFrequency==='number'?result.seconds!==selectedFrequency:result.period!==selectedFrequency))throw new Error('期权 K 线合约或周期不匹配。');chart.value=result;chartError.value='';chartSchedule.received(result.dataStatus)}
 catch(e){if(alive&&ticket===chartRequest&&version===generation){chartError.value=text(e);chartSchedule.failed()}}finally{if(alive&&ticket===chartRequest)chartLoading.value=false}
}
function refresh(){resetSchedules();void loadLinked();void loadContracts();void loadDepth();void loadChart()}
function invalidate(){resetSchedules();++generation;++linkedRequest;++chainRequest;++depthRequest;++chartRequest;linkedLoading.value=false;chainLoading.value=false;depthLoading.value=false;chartLoading.value=false}
watch(()=>props.futureSymbol,()=>{invalidate();linked.value=null;chain.value=null;depth.value=null;chart.value=null;chainId.value='';symbol.value='';side.value='ALL';strike.value='';linkedError.value='';chainError.value='';depthError.value='';chartError.value='';void loadLinked()})
watch(chainId,()=>{++chainRequest;chainLoading.value=false;chain.value=null;symbol.value='';if(chainId.value)void loadContracts()})
watch([side,strike],()=>{if(!contracts.value.some(c=>c.symbol===symbol.value))symbol.value=candidate()})
watch(symbol,()=>{++generation;++depthRequest;++chartRequest;depthLoading.value=false;chartLoading.value=false;depth.value=null;chart.value=null;depthError.value='';chartError.value='';void loadDepth();void loadChart()})
watch(frequency,()=>{chartSchedule.reset();++chartRequest;chartLoading.value=false;chart.value=null;chartError.value='';void loadChart()})
watch(()=>props.paused,value=>{if(value)invalidate();else refresh()})
function visibility(){if(document.hidden)invalidate();else if(!props.paused)refresh()}
onMounted(()=>{document.addEventListener('visibilitychange',visibility);void loadLinked();timer=window.setInterval(()=>{clock.value=Date.now();if(document.hidden||props.paused||!permitted.value)return;if(depthSchedule.due())void loadDepth();if(chartSchedule.due())void loadChart();if(chainSchedule.due())void loadContracts();if(linkedSchedule.due())void loadLinked()},1000)})
onUnmounted(()=>{document.removeEventListener('visibilitychange',visibility);alive=false;invalidate();window.clearInterval(timer)})
</script>
<template>
 <section v-if="permitted" class="option-watch" aria-label="对应合约期权盘口"><header class="option-heading"><div><p>LINKED OPTIONS / 精确标的关联</p><h3><ArrowLeftRight :size="17"/>对应合约的期权盘口</h3><span>期货 {{instrumentLabel(futureSymbol)}} → 实际交割合约 {{linked?.resolvedFuture?instrumentLabel(linked.resolvedFuture):'等待元数据'}}</span></div><button :disabled="paused" @click="refresh"><RefreshCw :size="14"/>刷新期权</button></header>
  <p v-if="linkedError" class="option-error" role="alert">{{linkedError}} <button @click="loadLinked">重试关联</button></p><p v-if="linked?.message" class="option-note">{{linked.message}}</p>
  <p v-if="linked&&!linked.chains.length" class="option-empty">当前交割合约暂无匹配的期货期权。仅使用真实标的映射，不替换其他月份。</p>
  <div v-if="linked?.chains.length" class="option-selectors"><label>期权到期日<select v-model="chainId" aria-label="关联期权到期日"><option v-for="c in linked.chains" :key="c.id" :value="c.id">{{formatTradingDate(c.expiry)}} · {{instrumentLabel(c.underlyingSymbol)}} · {{c.contractCount}} 合约</option></select></label><label>认购 / 认沽<select v-model="side" aria-label="期权认购认沽"><option value="ALL">全部</option><option value="CALL">认购期权</option><option value="PUT">认沽期权</option></select></label><label>行权价<input v-model="strike" aria-label="期权行权价搜索" placeholder="筛选行权价"/></label><label class="option-contract">期权合约<select v-model="symbol" aria-label="看盘期权合约"><option value="">选择具体期权合约</option><option v-for="c in contracts" :key="c.symbol" :value="c.symbol">{{c.optionClass==='CALL'?'认购':'认沽'}} · {{c.strike}} · {{instrumentLabel(c.symbol,c.name)}}</option></select></label></div>
  <p v-if="chainError" class="option-error" role="alert">{{chainError}}</p>
  <div v-if="selected" class="option-quote"><div><strong>{{instrumentLabel(selected.symbol,selected.name)}}</strong><small>{{instrumentName(selected.symbol,selected.name)}} · {{selected.optionClass==='CALL'?'认购':'认沽'}} · 行权价 {{n(selected.strike)}} · 到期 {{formatTradingDate(selected.expiry)}}</small></div><div><span>最新权利金</span><strong>{{n(depth?.lastPrice)}}</strong></div><div><span>{{stateLabel}}</span><time>{{formatTime(depth?.dataTimestamp)}}</time></div></div>
  <div v-if="symbol" class="option-grid"><section class="option-chart"><header><h4>期权 K 线与均线</h4><small>{{chart?.points.length??0}} 根 · {{periodLabel}}</small></header><div class="option-periods"><button v-for="p in LIVE_PERIODS" :key="p.value" :aria-pressed="frequency===p.value" :class="{chosen:frequency===p.value}" @click="frequency=p.value">{{p.label}}</button></div><p v-if="chartError" class="option-error" role="alert">{{chartError}} <button :disabled="paused" @click="loadChart">重试期权 K 线</button></p><TongdaxinChart v-if="chart?.points.length" :key="symbol+'-'+frequency" :points="chart.points" :symbol="symbol" :display-name="`${instrumentName(symbol,selected?.name)} · ${periodLabel}`" :height="420" :initial-visible-bars="70" :preserve-viewport-on-append="true" :time-label-mode="typeof frequency==='number'?'datetime-seconds':frequency==='MONTH'?'month':'calendar'" default-sub-chart="vol"/><p v-else class="option-empty">{{chartLoading?'正在订阅真实期权 K 线…':'暂无真实期权 K 线，等待行情。'}}</p><p class="option-note">{{chart?.source??'天勤期权行情'}} · {{chartError?'读取失败，保留上次快照':chart?.dataStatus==='FRESH'?'近时数据':'缓存 / 等待数据'}} · 历史不足 N 根时对应均线留空。</p></section>
   <section class="option-depth" aria-label="期权实时买卖盘口"><header><h4>期权盘口深度</h4><small>买 {{radar.bidCoverage}} / 卖 {{radar.askCoverage}} 档</small></header><p v-if="depthError" class="option-error" role="alert">{{depthError}} <button :disabled="paused" @click="loadDepth">重试期权盘口</button></p><div class="option-depth-head"><span>档位</span><span>权利金</span><span>挂单 / 手</span></div><div v-for="level in [...(depth?.asks??[])].sort((a,b)=>b.level-a.level)" :key="'ask'+level.level" class="option-depth-row sell"><i :style="{width:(level.price!=null?level.volume/maxVolume*100:0)+'%'}"/><span>卖 {{level.level}}</span><strong>{{n(level.price)}}</strong><b>{{level.price==null?'—':n(level.volume,0)}}</b></div><div class="option-spread"><span>买卖一价差</span><strong>{{n(radar.spread)}}</strong></div><div v-for="level in depth?.bids??[]" :key="'bid'+level.level" class="option-depth-row buy"><i :style="{width:(level.price!=null?level.volume/maxVolume*100:0)+'%'}"/><span>买 {{level.level}}</span><strong>{{n(level.price)}}</strong><b>{{level.price==null?'—':n(level.volume,0)}}</b></div><p v-if="!depth" class="option-empty">等待真实期权盘口，缺失档位保持为空。</p><div class="option-ticks"><h4>近 60 秒成交增量</h4><div v-for="t in radar.ticks.slice(0,20)" :key="t.id+t.timestamp" class="option-tick" :class="t.side==='BUY'?'buy':t.side==='SELL'?'sell':''"><time>{{formatTime(t.timestamp).slice(-8)}}</time><strong>{{n(t.price)}}</strong><span>{{n(t.volume,0)}} 手</span><small>{{t.side==='BUY'?'估算买向':t.side==='SELL'?'估算卖向':'方向未定'}}</small></div><p v-if="!radar.ticks.length" class="option-empty">该窗口暂无成交增量</p></div></section></div>
  <p class="option-note">期权大额成交使用独立的手数阈值。盘口只描述可见挂单，Tick 增量可能包含多笔成交；方向不是交易所逐笔委托标志。</p>
 </section>
 <section v-else class="option-watch option-empty">当前角色没有期权读取权限，期货看盘仍可使用。</section>
</template>
<style scoped>
.option-heading span,.option-quote strong,.option-quote small{overflow-wrap:anywhere;min-width:0}
.option-watch{display:grid;gap:1rem;min-width:0;color:#dce6ed;border:1px solid #2a3a49;border-radius:8px;background:#14212c;padding:1.1rem}.option-heading{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:1rem}.option-heading p{font:.58rem var(--font-numeric);letter-spacing:.1em;color:#96b9cd;margin:0}.option-heading h3{display:flex;gap:.5rem;align-items:center;font-size:.95rem;font-weight:500;margin:.7rem 0}.option-heading span{font-size:.65rem;color:#94a5b6}.option-watch button{display:inline-flex;align-items:center;justify-content:center;gap:.4rem;color:#dce6ed;background:#203140;border:1px solid #3a5061;border-radius:4px;font:.65rem var(--font-sans);padding:.55rem .7rem;cursor:pointer}.option-watch button:disabled{opacity:.45;cursor:default}.option-selectors{display:flex;align-items:end;gap:.8rem;flex-wrap:wrap;background:#182430;border:1px solid #2a3a49;padding:1rem;border-radius:5px}.option-selectors label{display:grid;gap:.4rem;flex:1;min-width:8rem;font-size:.62rem;color:#94a5b6}.option-selectors .option-contract{flex:1.8}.option-selectors input,.option-selectors select{font:.68rem var(--font-sans);background:#101d28;color:#dce6ed;border:1px solid #354b5d;padding:.6rem;border-radius:4px;min-width:0;width:100%}.option-quote{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;padding:.5rem}.option-quote>div{display:grid;gap:.4rem}.option-quote strong{font:500 1rem var(--font-numeric)}.option-quote small,.option-quote span{font-size:.6rem;color:#94a5b6}.option-quote time{font:.65rem var(--font-numeric)}.option-grid{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:1rem;min-width:0}.option-chart,.option-depth{background:#182430;border:1px solid #2a3a49;border-radius:6px;min-width:0;overflow:hidden}.option-chart>header,.option-depth>header{display:flex;align-items:center;justify-content:space-between;gap:.7rem;padding:.85rem 1rem;border-bottom:1px solid #2a3a49}.option-watch h4{font-size:.72rem;font-weight:500;margin:0}.option-watch header small{color:#94a5b6;font-size:.58rem}.option-periods{display:flex;gap:.3rem;flex-wrap:wrap;padding:.65rem .8rem}.option-periods button{background:transparent;border-color:transparent;font-size:.6rem;padding:.3rem .4rem;color:#94a5b6}.option-periods button.chosen{background:#2d475a;border-color:#42647b;color:#dce6ed}.option-note,.option-error{font-size:.6rem;line-height:1.9;padding:.6rem .9rem;margin:0;color:#94a5b6}.option-error{color:#e3c390;background:#4d3b2230}.option-error button{font-size:.58rem;padding:.2rem .4rem;margin-left:.4rem}.option-empty{padding:2rem .8rem;text-align:center;color:#94a5b6;font-size:.65rem;line-height:1.8}.option-depth-head,.option-depth-row{display:grid;grid-template-columns:2.5rem 1fr 4.2rem;gap:.5rem;text-align:right;padding:.55rem .8rem;font:.65rem var(--font-numeric);position:relative}.option-depth-head{color:#94a5b6;font-size:.56rem}.option-depth-head span:first-child,.option-depth-row span{text-align:left;color:#94a5b6}.option-depth-row i{position:absolute;right:0;top:2px;bottom:2px;opacity:.12;background:currentColor}.option-depth-row strong,.option-depth-row b,.option-depth-row span{position:relative;font-weight:400}.buy{color:#ef8e83}.sell{color:#66c4a1}.option-spread{display:flex;justify-content:space-between;padding:.8rem;border-block:1px solid #2a3a49;background:#101d28;font-size:.63rem}.option-spread strong{font-family:var(--font-numeric)}.option-ticks{border-top:1px solid #2a3a49;margin-top:.5rem;max-height:20rem;overflow:auto}.option-ticks h4{padding:.8rem}.option-tick{display:grid;grid-template-columns:1fr .8fr .8fr 1fr;gap:.4rem;padding:.5rem .7rem;border-top:1px solid #253443;text-align:right;font:.58rem var(--font-numeric)}.option-tick time{text-align:left;color:#94a5b6}.option-tick small{font-size:.54rem}.option-tick strong{font-weight:400}@media(max-width:1100px){.option-grid{grid-template-columns:minmax(0,1fr) 260px}.option-selectors label{flex-basis:40%}}@media(max-width:850px){.option-grid{grid-template-columns:minmax(0,1fr)}.option-watch{padding:.8rem}.option-selectors{padding:.8rem}.option-selectors label{min-width:0}.option-selectors .option-contract{flex-basis:100%}.option-quote strong{font-size:.85rem;overflow-wrap:anywhere}}
</style>
